const test = require('node:test');
const assert = require('node:assert/strict');
const { CheckoutHandler, CancelHandler } = require('../../../dist/apps/api/src');
const { createCommerceSystem, sequenceIds } = require('../../../dist/packages/checkout/src');

const input = { customerId: 'customer', sku: 'widget', quantity: 1, unitPriceCents: 6000, promotionBps: 0 };
const principal = { tenantId: 'acme', userId: 'user' };
function setup() {
  const system = createCommerceSystem({ now: () => 1000, ids: sequenceIds('api') });
  system.inventory.stock('widget', 3);
  return { ...system, place: new CheckoutHandler(system.checkout), cancel: new CancelHandler(system.cancellation) };
}

test('checkout binds tenant to the authenticated principal despite forged input', () => {
  const system = setup();
  const result = system.place.handle(principal, { ...input, tenantId: 'beta' });
  assert.equal(result.ok, true);
  assert.equal(system.orders.findForTenant('acme', result.orderId).tenantId, 'acme');
  assert.equal(system.orders.findForTenant('beta', result.orderId), undefined);
  assert.equal(system.payments.attempts()[0].tenantId, 'acme');
});

test('cross-tenant cancellation cannot refund or release an order', () => {
  const system = setup();
  const result = system.place.handle(principal, input);
  assert.throws(() => system.cancel.handle({ ...principal, tenantId: 'beta' }, result.orderId), { code: 'order_not_found' });
  assert.equal(system.orders.findForTenant('acme', result.orderId).state, 'paid');
  assert.deepEqual(system.payments.refunds(), []);
  assert.equal(system.payments.attempts()[0].state, 'captured');
  assert.equal(system.inventory.reservations()[0].state, 'committed');
  assert.equal(system.inventory.available('widget'), 2);
  assert.deepEqual(system.cancel.handle(principal, result.orderId), { cancelled: true });
  assert.equal(system.inventory.available('widget'), 3);
});

test('unauthenticated checkout and cancellation have no side effects', () => {
  const system = setup();
  assert.throws(() => system.place.handle(undefined, input), /unauthorized/);
  assert.deepEqual(system.payments.attempts(), []);
  assert.deepEqual(system.orders.all(), []);
  assert.deepEqual(system.outbox.pending(), []);
  assert.equal(system.inventory.available('widget'), 3);
  const result = system.place.handle(principal, input);
  assert.throws(() => system.cancel.handle(undefined, result.orderId), /unauthorized/);
  assert.deepEqual(system.payments.refunds(), []);
  assert.equal(system.orders.findForTenant('acme', result.orderId).state, 'paid');
  assert.equal(system.inventory.available('widget'), 2);
});

const test = require('node:test');
const assert = require('node:assert/strict');
const { DeliveryRunner } = require('../../../dist/apps/worker/src');
const { Outbox, DeliveryLog, DeliveryAuditLog, DeliveryWorker } = require('../../../dist/packages/fulfillment/src');

test('runner forwards the tenant so delivery and audit remain scoped', () => {
  assert.equal(typeof DeliveryAuditLog, 'function', 'independent audit log is exported');
  const outbox = new Outbox();
  const audit = new DeliveryAuditLog();
  const runner = new DeliveryRunner(new DeliveryWorker(outbox, new DeliveryLog(), audit));
  for (const tenantId of ['beta', 'acme']) outbox.append({ tenantId, id: 'shared', type: 'order.placed', payload: {} });
  assert.equal(runner.run('other', () => assert.fail('wrong tenant')), undefined);
  assert.throws(() => runner.run('', () => assert.fail('invalid scope')), /invalid tenant/);
  const sent = [];
  assert.equal(runner.run('acme', e => { sent.push(e.tenantId); return 'sent'; }), 'sent');
  assert.deepEqual(sent, ['acme']);
  assert.deepEqual(outbox.pending().map(e => e.tenantId), ['beta']);
  assert.equal(audit.forTenant('acme').length, 1);
  assert.deepEqual(audit.forTenant('beta'), []);
});

const test = require('node:test');
const assert = require('node:assert/strict');
const { OrderRepository, createCommerceSystem, sequenceIds } = require('../../../dist/packages/checkout/src');

const input = { customerId: 'customer', sku: 'widget', quantity: 1, unitPriceCents: 6000, promotionBps: 0 };
const order = (tenantId, id = 'shared') => ({
  id, tenantId, customerId: 'customer', sku: 'widget', quantity: 1, totalCents: 6000,
  paymentId: `${tenantId}-payment`, reservationId: `${tenantId}-reservation`,
  eventId: `${tenantId}-event`, state: 'paid',
});

test('equal order IDs in different tenants do not overwrite each other', () => {
  const orders = new OrderRepository();
  orders.save(order('acme'));
  orders.save(order('beta'));
  assert.equal(orders.findForTenant('acme', 'shared')?.tenantId, 'acme');
  assert.equal(orders.findForTenant('beta', 'shared')?.tenantId, 'beta');
  assert.equal(orders.all().length, 2);
  assert.equal(orders.findForTenant('other', 'shared'), undefined);
});

test('tenant and order keys preserve delimiters, escaping and whitespace', () => {
  const orders = new OrderRepository();
  const keys = [['a:b', 'c'], ['a', 'b:c'], ['a"', '\\b'], ['a', '"\\b'], [' acme ', 'shared'], ['acme', 'shared']];
  for (const [tenantId, id] of keys) orders.save(order(tenantId, id));
  for (const [tenantId, id] of keys) assert.equal(orders.findForTenant(tenantId, id)?.tenantId, tenantId);
  assert.equal(orders.all().length, keys.length);
});

test('saving the same tenant and order ID updates that order', () => {
  const orders = new OrderRepository();
  orders.save(order('acme'));
  orders.save({ ...order('acme'), state: 'cancelled' });
  assert.equal(orders.findForTenant('acme', 'shared').state, 'cancelled');
  assert.equal(orders.all().length, 1);
});

test('cancelling one of two equal order IDs leaves the other tenant paid and reserved', () => {
  const system = createCommerceSystem({ now: () => 1000, ids: sequenceIds('cancel') });
  system.inventory.stock('widget', 3);
  for (const tenantId of ['acme', 'beta']) {
    const entry = order(tenantId);
    system.payments.charge({ tenantId, paymentId: entry.paymentId, amountCents: 6000 });
    system.inventory.reserve({ id: entry.reservationId, sku: 'widget', quantity: 1, expiresAt: 2000 });
    system.inventory.commit(entry.reservationId);
    system.orders.save(entry);
  }
  assert.deepEqual(system.cancellation.cancel({ tenantId: 'acme', orderId: 'shared' }), { cancelled: true });
  assert.equal(system.orders.findForTenant('acme', 'shared').state, 'cancelled');
  assert.equal(system.orders.findForTenant('beta', 'shared').state, 'paid');
  assert.deepEqual(system.payments.refunds(), [{ paymentId: 'acme-payment', amountCents: 6000 }]);
  assert.deepEqual(system.payments.attempts().map(p => p.state), ['refunded', 'captured']);
  assert.deepEqual(system.inventory.reservations().map(r => r.state), ['released', 'committed']);
  assert.equal(system.inventory.available('widget'), 2);
  assert.deepEqual(system.cancellation.cancel({ tenantId: 'acme', orderId: 'shared' }), { cancelled: false });
  assert.equal(system.payments.refunds().length, 1);
});

for (const tenantId of [undefined, null, '', '  ', 123]) {
  test(`repository rejects invalid tenant ${JSON.stringify(tenantId)} without writes`, () => {
    const orders = new OrderRepository();
    assert.throws(() => orders.save(order(tenantId)), /invalid tenant/);
    assert.throws(() => orders.findForTenant(tenantId, 'shared'), /invalid tenant/);
    assert.deepEqual(orders.all(), []);
  });

  test(`checkout rejects invalid tenant ${JSON.stringify(tenantId)} before side effects`, () => {
    let allocated = 0;
    const system = createCommerceSystem({ now: () => 1000, ids: { next: kind => `${kind}-${++allocated}` } });
    system.inventory.stock('widget', 3);
    assert.throws(() => system.checkout.place({ ...input, tenantId }), /invalid tenant/);
    assert.equal(allocated, 0);
    assert.equal(system.inventory.available('widget'), 3);
    assert.deepEqual(system.inventory.reservations(), []);
    assert.deepEqual(system.payments.attempts(), []);
    assert.deepEqual(system.orders.all(), []);
    assert.deepEqual(system.outbox.pending(), []);
  });
}

export function assertTenantId(value: TenantId): TenantId {
  if (typeof value !== 'string' || value.trim().length === 0) throw new Error('invalid tenant');
  return value;
}

import { assertTenantId } from '../../core/src';

export interface DeliveryAuditRecord {
  tenantId: string;
  eventId: string;
  result: string;
}

export class DeliveryAuditLog {
  private readonly records: DeliveryAuditRecord[] = [];

  record(entry: DeliveryAuditRecord): void {
    assertTenantId(entry.tenantId);
    this.records.push({ ...entry });
  }

  forTenant(tenantId: string): DeliveryAuditRecord[] {
    assertTenantId(tenantId);
    return this.records.filter((record) => record.tenantId === tenantId).map((record) => ({ ...record }));
  }
}

has(tenantId: string, eventId: string): boolean {
  assertTenantId(tenantId);
  return this.records.some((record) => record.tenantId === tenantId && record.eventId === eventId);

this.deliveries.record({ tenantId, eventId: event.id, result });
this.outbox.markDelivered(tenantId, event.id);
this.audit.record({ tenantId, eventId: event.id, result });

markDelivered(tenantId: string, eventId: string): void {
  assertTenantId(tenantId);
  const record = this.records.find((candidate) => candidate.event.tenantId === tenantId && candidate.event.id === eventId);

export function pendingEventsForTenant(outbox: Outbox, tenantId: string): DomainEvent[] {
  assertTenantId(tenantId);
  return outbox.pending().filter((event) => event.tenantId === tenantId);
}

const test = require('node:test');
const assert = require('node:assert/strict');
const { Outbox, DeliveryLog, DeliveryAuditLog, DeliveryWorker, pendingEventsForTenant } = require('../../../dist/packages/fulfillment/src');
const { createCommerceSystem, sequenceIds } = require('../../../dist/packages/checkout/src');

const event = (tenantId, id = 'shared') => ({ tenantId, id, type: 'order.placed', payload: { orderId: 'order' } });
function setup() {
  assert.equal(typeof DeliveryAuditLog, 'function', 'independent audit log is exported');
  const outbox = new Outbox();
  const deliveries = new DeliveryLog();
  const audit = new DeliveryAuditLog();
  return { outbox, deliveries, audit, worker: new DeliveryWorker(outbox, deliveries, audit) };
}

test('checkout tags its event with the order tenant', () => {
  const system = createCommerceSystem({ now: () => 1000, ids: sequenceIds('events') });
  system.inventory.stock('widget', 1);
  const result = system.checkout.place({ tenantId: 'acme', customerId: 'customer', sku: 'widget', quantity: 1, unitPriceCents: 6000, promotionBps: 0 });
  assert.equal(result.ok, true);
  assert.equal(system.outbox.pending()[0].tenantId, 'acme');
  assert.deepEqual(system.outbox.pending()[0].payload, { orderId: result.orderId });
});

test('outbox deduplicates only the same tenant and event ID', () => {
  const outbox = new Outbox();
  outbox.append(event('acme'));
  outbox.append(event('beta'));
  outbox.append(event('acme'));
  assert.deepEqual(outbox.pending().map(e => e.tenantId), ['acme', 'beta']);
});

test('marking one tenant delivered leaves the same event ID pending for another', () => {
  const outbox = new Outbox();
  outbox.append(event('acme'));
  outbox.append(event('beta'));
  outbox.markDelivered('acme', 'shared');
  assert.deepEqual(outbox.pending().map(e => e.tenantId), ['beta']);
  assert.throws(() => outbox.markDelivered('other', 'shared'), /outbox event not found/);
  assert.deepEqual(outbox.pending().map(e => e.tenantId), ['beta']);
});

test('delivery identity preserves delimiter-containing and exact tenant strings', () => {
  const outbox = new Outbox();
  const deliveries = new DeliveryLog();
  const pairs = [['a:b', 'c'], ['a', 'b:c'], [' acme ', 'shared'], ['acme', 'shared']];
  for (const [tenantId, id] of pairs) {
    outbox.append(event(tenantId, id));
    deliveries.record({ tenantId, eventId: id, result: 'sent' });
  }
  assert.equal(outbox.pending().length, 4);
  assert.equal(deliveries.all().length, 4);
  for (const [tenantId, id] of pairs) assert.equal(deliveries.has(tenantId, id), true);
  outbox.markDelivered('a:b', 'c');
  assert.deepEqual(outbox.pending().map(e => [e.tenantId, e.id]), [['a', 'b:c'], [' acme ', 'shared'], ['acme', 'shared']]);
});

test('worker sends and audits only its tenant even when another tenant is first', () => {
  const { outbox, deliveries, audit, worker } = setup();
  outbox.append(event('beta'));
  outbox.append(event('acme'));
  const sent = [];
  const send = e => { sent.push(e.tenantId); return 'sent'; };
  assert.equal(worker.deliverNext('acme', send), 'sent');
  assert.deepEqual(sent, ['acme']);
  assert.deepEqual(outbox.pending().map(e => e.tenantId), ['beta']);
  assert.equal(deliveries.has('acme', 'shared'), true);
  assert.equal(deliveries.has('beta', 'shared'), false);
  assert.deepEqual(audit.forTenant('acme'), [{ tenantId: 'acme', eventId: 'shared', result: 'sent' }]);
  assert.deepEqual(audit.forTenant('beta'), []);
  assert.equal(worker.deliverNext('acme', send), undefined);
  assert.deepEqual(sent, ['acme']);
  assert.equal(audit.forTenant('acme').length, 1);
  assert.equal(worker.deliverNext('beta', send), 'sent');
  assert.deepEqual(sent, ['acme', 'beta']);
  assert.equal(deliveries.has('beta', 'shared'), true);
  assert.deepEqual(audit.forTenant('beta'), [{ tenantId: 'beta', eventId: 'shared', result: 'sent' }]);
  assert.deepEqual(outbox.pending(), []);
});

test('existing delivery bookkeeping skips a send without adding an audit', () => {
  const { outbox, deliveries, audit, worker } = setup();
  outbox.append(event('acme'));
  deliveries.record({ tenantId: 'acme', eventId: 'shared', result: 'sent' });
  assert.equal(worker.deliverNext('acme', () => assert.fail('already delivered')), undefined);
  assert.deepEqual(audit.forTenant('acme'), []);
});

test('failed sends stay pending and a later successful retry is audited once', () => {
  const { outbox, deliveries, audit, worker } = setup();
  outbox.append(event('acme'));
  assert.throws(() => worker.deliverNext('acme', () => { throw new Error('send failed'); }), /send failed/);
  assert.equal(outbox.pending().length, 1);
  assert.deepEqual(deliveries.all(), []);
  assert.deepEqual(audit.forTenant('acme'), []);
  assert.equal(worker.deliverNext('acme', () => 'retried'), 'retried');
  assert.deepEqual(outbox.pending(), []);
  assert.deepEqual(deliveries.all(), [{ tenantId: 'acme', eventId: 'shared', result: 'retried' }]);
  assert.deepEqual(audit.forTenant('acme'), [{ tenantId: 'acme', eventId: 'shared', result: 'retried' }]);
});

test('audit preserves independent observations while delivery bookkeeping deduplicates', () => {
  const { deliveries, audit } = setup();
  const entry = { tenantId: 'acme', eventId: 'shared', result: 'sent' };
  deliveries.record(entry);
  deliveries.record(entry);
  audit.record(entry);
  audit.record(entry);
  audit.record({ ...entry, tenantId: 'beta' });
  assert.equal(deliveries.all().length, 1);
  assert.equal(audit.forTenant('acme').length, 2);
  assert.equal(audit.forTenant('beta').length, 1);
  assert.deepEqual(audit.forTenant('other'), []);
});

test('audit input and output mutations cannot rewrite stored tenant history', () => {
  const { audit } = setup();
  const entry = { tenantId: 'acme', eventId: 'shared', result: 'sent' };
  audit.record(entry);
  entry.tenantId = 'beta';
  entry.result = 'changed';
  const entries = audit.forTenant('acme');
  assert.equal(entries.length, 1);
  entries[0].tenantId = 'beta';
  entries[0].result = 'changed';
  entries.push({ tenantId: 'acme', eventId: 'injected', result: 'sent' });
  assert.deepEqual(audit.forTenant('acme'), [{ tenantId: 'acme', eventId: 'shared', result: 'sent' }]);
  assert.deepEqual(audit.forTenant('beta'), []);
});

for (const tenantId of [undefined, null, '', '  ', 123]) {
  test(`outbox rejects invalid tenant ${JSON.stringify(tenantId)} without mutation`, () => {
    const outbox = new Outbox();
    outbox.append(event('acme'));
    assert.throws(() => outbox.append(event(tenantId)), /invalid tenant/);
    assert.throws(() => outbox.markDelivered(tenantId, 'shared'), /invalid tenant/);
    assert.equal(typeof pendingEventsForTenant, 'function');
    assert.throws(() => pendingEventsForTenant(outbox, tenantId), /invalid tenant/);
    assert.deepEqual(pendingEventsForTenant(outbox, 'acme').map(e => e.id), ['shared']);
    assert.deepEqual(pendingEventsForTenant(outbox, 'beta'), []);
  });

  test(`delivery and audit reject invalid tenant ${JSON.stringify(tenantId)} without side effects`, () => {
    const { outbox, deliveries, audit, worker } = setup();
    outbox.append(event('acme'));
    assert.throws(() => deliveries.record({ tenantId, eventId: 'shared', result: 'sent' }), /invalid tenant/);
    assert.throws(() => deliveries.has(tenantId, 'shared'), /invalid tenant/);
    assert.throws(() => audit.record({ tenantId, eventId: 'shared', result: 'sent' }), /invalid tenant/);
    assert.throws(() => audit.forTenant(tenantId), /invalid tenant/);
    assert.throws(() => worker.deliverNext(tenantId, () => assert.fail('invalid scope must not send')), /invalid tenant/);
    assert.equal(outbox.pending().length, 1);
    assert.deepEqual(deliveries.all(), []);
    assert.deepEqual(audit.forTenant('acme'), []);
  });
}

